package Game;

/** The text of the in-game Help, part 2: the Me tab, the game systems, the terminal and the reference pages. See HelpPages for the notes. */
final class HelpPagesMore {
    private HelpPagesMore() { }

    private static final String G4 = HelpPages.G4, G7 = HelpPages.G7, G8 = HelpPages.G8, G9 = HelpPages.G9;

    // ================================================================== Me tab
    static void meTab() {
        HelpContent.add("me", "Me tab", G4, "Your character, people, places and work: every button of the second tab.", "me tab stats backpack techniques biography journal story run stats edit self relations family squad companions people here lineage locations painted map quests digest cheats help",
                "lead The second tab is about **you**: who you are, what you carry, who you know, where you have been. Every button opens a window; none of them uses a turn. (The things you do each turn, and the Help button, are on the [[move|Move tab]].)",
                "img dock-me.png|The Me tab.",
                "h2 Character",
                "table Button|What it opens|Command|Page",
                "row ((Stats))|Your character sheet. {I}|`i`|[[stats]]",
                "row ((Backpack))|Gear, materials, pills, arrays, goods. {V}|`bag`|[[backpack]]",
                "row ((Techniques))|The backpack window on its Techniques tab.|`techniques`|[[techniques]]",
                "row ((Biography))|Charts and life events. {J}|`journal`|[[biography]]",
                "row ((Journal))|Your story so far: what the chronicle says about you, your recent notices.|`journal`|[[biography]]",
                "row ((Story))|Objectives of a Story start.|`story`|[[story]]",
                "row ((Oldest Order))|The Journal of the Palace of the Oldest Order: what it asks of you now, the road so far, the places you have read and what you learned, the scenes you can read again.|`lore`|[[lore]]",
                "row ((Run stats))|Statistics of your whole run, the hall of fame.|`runstats`|[[story]]",
                "row ((Edit Self))|The character editor: name, trait, potential, alignment, gender.|`e`|[[cheats]]",
                "h2 People",
                "table Button|What it opens|Command|Page",
                "row ((Relations))|Everyone you have a relationship with. {R}|`r`|[[relations]]",
                "row ((Family))|Family tree and relationship graph. {F}|`family`|[[family]]",
                "row ((Squad & Sect))|Your party and your sect.|`party`|[[squad]]",
                "row ((Companions))|Tamed beasts (the Backpack's Companions tab).|`companions`|[[companions]]",
                "row ((People here))|The cultivators in your tile, numbered for commands.|`people`|[[locations]]",
                "row ((Lineage))|Your past lives.|`lineage`|[[reincarnation]]",
                "h2 Places and work",
                "table Button|What it opens|Command|Page",
                "row ((Locations))|Known places with distances. {L}|`l`|[[locations]]",
                "row ((Here))|Describes the tile you stand on and what you can do in it.|`here`|[[locations]]",
                "row ((Quest Log))|The Quest Log, the one quest window.|`q`|[[quests]]",
                "h2 System",
                "table Button|What it opens|Command|Page",
                "row ((Cheats))|Developer menu: give stones, set level...|`z`|[[cheats]]",
                "tip The Me tab is scrollable: if the window is short, scroll for the lower groups. The ((?)) button in a window's top row opens the matching page of this Help.",
                "see stats backpack relations locations quests");

        HelpContent.add("stats", "Stats: your character sheet", G4, "Every line of the Stats window.", "stats character sheet potential rope wealth profession fighting level weapon armor martial movement record sect place spouse children companions conditions poisoned control",
                "lead ((Stats)) or {I} opens a sheet that refreshes by itself. Its parts, top to bottom:",
                "img win-stats.png|The Stats window.",
                "* **Name and title**, then your trait, alignment, gender, age and lifespan (and “life 2” after a reincarnation).",
                "* **Major · realm** (low, mid, high, peak) and **Lv**, with the cultivation bar and an estimate of **weeks to the next level**. See [[cultivation]].",
                "h2 Fortune",
                "table Line|Meaning",
                "row Potential|Your ceiling (a word while hidden). See [[cultivation]].",
                "row Rope|How far your potential can carry you before you must reincarnate (see [[reincarnation]]).",
                "row Wealth|In spirit stones.",
                "row Profession|Your craft level and how many items you made.",
                "h2 Combat",
                "table Line|Meaning",
                "row Fighting level|The number that decides fights: (level + weapon + armour + martial technique + movement technique) / 5, plus bonuses, and your companions add. See [[combat]].",
                "row Weapon, Armor|What you wear (click to open the [[backpack]]).",
                "row Martial, Movement|Your best techniques: name, level / potential. See [[techniques]].",
                "row Record|Kills.",
                "h2 Home and family",
                "p Your sect and rank (click for [[squad]]), the place you stand in (click for details), spouse, children (a link to the [[family]] tree) and companions.",
                "h2 Conditions and control",
                "p **Conditions** (shown only when you have some): nourished, drunk, inspired, **POISONED** with its level and weeks left, or a poisoned blade ([[life-arts]]). **Control** shows your mode, duties and current quest. The last line has links to the other windows.",
                "see backpack techniques combat");

        HelpContent.add("backpack", "Backpack and equipment", G4, "Gear, techniques, materials, pills, goods and companions in one window.", "backpack bag gear equip sell consume pills materials arrays goods food wine poison eat drink make play coat companions items weapon armor enchant",
                "lead ((Backpack)) or {V} opens a window with five tabs.",
                "h2 Gear",
                "img win-backpack-gear.png|The Gear tab.",
                "p The top lines show what you wear and your fighting level. The table lists everything you carry: number, item, kind, level, enchantment and, for gear, the **fighting level you would have if you wore it** (▲ better, ▼ worse, = same). Select an item to see the comparison; items have a picture icon.",
                "table Button|What it does|Command",
                "row ((Equip selected))|Wear the selected weapon or armour.|`equip <n>`",
                "row ((Equip best))|Wear the strongest you carry.|`equip`",
                "row ((Sell selected))|Sell one item (in a city).|`sell <n>`",
                "row ((Sell all (city)))|Sell everything you do not need: it keeps what you wear, your best spare weapon and armour, and your best instrument. Merchant shops that pay at least half price are used first, otherwise the city pool pays 50%.|`sell`",
                "row ((Consume pills))|Use your pills (cultivation, potential...).|`consume`",
                "p Item **levels** run 1-10 like realms; a better level costs far more ([[economy]]). In MANUAL mode the game does not swap your gear for you unless you turn on that setting ([[settings]]).",
                "h2 Techniques",
                "img win-backpack-techniques.png|The Techniques tab.",
                "p See [[techniques]]. ((Library)) opens the technique shop of the city you stand in.",
                "h2 Materials, pills, arrays",
                "p The raw stacks you carry: herbs and metals (from `forage` and `mine`), blood (taken from kills), pills and arrays. Arrays are installed in a place with `install` and protect its features ([[sect]]).",
                "h2 Food, wine, poison",
                "p Portions you made or bought, with your current **conditions**. Buttons: ((Eat)), ((Drink)), ((Make food)), ((Make wine)), ((Make poison)), ((Make instrument)), ((Play)), ((Coat blade)). Only the right **trait** can make each (Chef, Drunken, Poisoner, Musician). See [[life-arts]].",
                "h2 Companions",
                "p Tamed beasts. See [[companions]].",
                "see techniques companions life-arts economy");

        HelpContent.add("techniques", "Techniques", G4, "Martial and movement techniques: slots, mastery, where to get them.", "techniques martial movement slot mastery library learn level potential maker upgrade heaven sect library",
                "lead A **technique** is a learned fighting or movement art. Two kinds matter: **Martial** (how you strike) and **Movement** (how you move and escape). Each adds to your fighting level.",
                "img win-backpack-techniques.png|The Techniques tab of the backpack window.",
                "* The table shows each technique's **slot** (Martial, Martial 2, Movement, Movement 2, or just *known*), name, kind, **level**, **potential** (its ceiling), a **mastery** bar (level / potential) and who made it.",
                "* The game uses the **strongest technique of each kind automatically**. Practising and winning fights raise its level toward its potential. A Heavenly Root trait upgrades techniques faster.",
                "* Movement also helps you **flee**: someone with both a higher level and a better movement technique escapes almost always.",
                "h2 Where to get them",
                "* **City library** ((Market)) / ((Library)): buy with spirit stones (potential squared times 1,000 each); a learned technique starts at one fifth of its level.",
                "* **Sect library**: members pay sect points; it starts at one third of its level ([[sect]]).",
                "* **Dungeons**: Lost Ruins hold a technique, Martial Trials upgrade one ([[world-events]]); a **Heaven-sent treasure** is a rare one.",
                "* Kills sometimes upgrade a technique. **Innovative** characters invent techniques and sell them to libraries; you can sell yours with ((Sell my best technique here)).",
                "see market combat backpack");

        HelpContent.add("relations", "Relations", G4, "Everyone you have a relationship with.", "relations relationship friend rival enemy bond family spouse acquaintance like dislike value",
                "lead ((Relations)) or {R} lists everybody who knows you well enough to have an opinion.",
                "img win-relations.png|The Relations window.",
                "p The header shows your spouse and parents (click a name to open them). The **Find** box and the drop-down (everyone, friends, rivals and enemies, family) filter the table; each row has the name, the bond, level, whether alive and where they are.",
                "table Value|Bond",
                "row 3|best friend",
                "row 2|close friend",
                "row 1|friend",
                "row 0|acquaintance (the relationship is dropped)",
                "row -1|dislike",
                "row -2|rival",
                "row -3|arch-enemy",
                "p Bonds change when you **talk**, spar, give gifts, fight, travel together, or when a friend is killed. They matter: friends never kill you in a fight, rivals do 1 time in 4, arch-enemies 3 in 4 ([[combat]]). Two single, unrelated adults of the opposite sex who reach the top bond may marry, and friends who die give you a **Revenge** quest ([[quests]]).",
                "see family combat browse");

        HelpContent.add("family", "Family and relationships", G4, "The family tree, relationship graph, past lives and anyone's web.", "family tree graph spouse children parents siblings marriage birth pregnancy lineage past lives web ancestors",
                "lead ((Family)) or {F} opens a window with six tabs.",
                "img win-family.png|The Family window.",
                "table Tab|Shows",
                "row Family tree|You in the middle, parents and grandparents above, children and grandchildren below; spouse in gold. Click a person to open them. Deceased relatives are greyed with †.",
                "row Relationship graph|You with up to 16 people around you. **Green** lines are friends, **red** rivals, **gold** your spouse, **blue** family; thicker means stronger.",
                "row Family list|The same as text.",
                "row Relationship list|Everyone you know as text.",
                "row Past lives|Your earlier lives after reincarnation ([[reincarnation]]).",
                "row Anyone's web|Type a name or `#id` and press ((Show)) to see that person's relationship web.",
                "h2 Marriage and children",
                "* Marriage happens when a relationship reaches the top level (3) between two single, unrelated adults (18+) of the opposite sex. The wife takes the husband's family name.",
                "* A child is born about 40 weeks after conception; children inherit the same-sex parent's techniques, a potential at least the parents' average, and the parents' sect. The duty *family* has your character try for a child ([[duties]]).",
                "* A spouse in your tile gives both of you a chance of extra cultivation ([[cultivation]]). When you die, you may take over a child ([[first-steps]]).",
                "see relations reincarnation duties");

        HelpContent.add("squad", "Squad and sect", G4, "Your party of cultivators and your sect.", "squad party group invite leave disband sect members promote recruit join resign rules leader follower",
                "lead ((Squad & Sect)) opens one window with two halves.",
                "img win-squad.png|The Squad & Sect window.",
                "h2 Squad (top)",
                "p A **squad** (party) is a leader and followers who travel together and **fight beasts together**. The table lists the leader, members and your companion beasts. A squad holds at most 4 members, or 12 if the leader is a Leader trait who is neither a sect master nor a city lord.",
                "table Button|What it does|Command",
                "row ((Invite someone here…))|Ask for a person in your tile by `#id` (or leave it empty for someone suitable). They accept if they like you, or are not hostile, within a realm of you, with a coin toss.|`invite [#id]`",
                "row ((Leave squad))|Leave the party.|`leave`",
                "row ((Disband))|Break up your squad (asks first).|`disband`",
                "row ((Companions))|Open the companion beasts.|`companions`",
                "h2 Sect (bottom)",
                "p Your sect, its master, rules, and a table of its members by rank. **Double-click** a row to open the person. Buttons: ((Promote selected)) (master: Outer Disciple to Inner to Elder), ((Recruit (random here))), ((Sect details)), ((Recruitment rules…)), ((Join sect here)), ((Resign)) (asks first; you lose your rank and sect points). More in [[sect]] and [[manage]].",
                "see sect manage companions");

        HelpContent.add("companions", "Companion beasts", G4, "Taming, feeding and releasing beasts.", "companions taming tamer beast pet feed release tame cap fight bonus soul waiting",
                "lead Beasts can become your companions: they follow you, cultivate, and add to your fighting level. Open them from the ((Companions)) button or the backpack's last tab.",
                "img win-companions.png|Companions.",
                "p The table shows each beast (a pet name chosen when it joins), level, potential, age and how much it **adds to your fighting level** (its level, capped by yours, divided by 10). The header shows how many you keep out of how many you may.",
                "table Button|What it does|Command",
                "row ((Tame a beast here))|Tries to tame one beast in your tile. Chance: 35 plus 3 per level you are above it (+30 for a Beast Tamer, +10 with an instrument, +10 if Friendly), between 5% and 95%. A beast more than 5 levels above you is refused; a failed try may make it attack.|`tame`",
                "row ((Feed selected))|Give it a portion of food: it cultivates for as many weeks as the food's level.|`feed <n>`",
                "row ((Release selected))|Send it back to the wild for good (asks first).|`release <n>`",
                "p **How many?** A **Beast Tamer** keeps your Major level plus one; everyone else may keep one. Companions follow you everywhere, never take a turn of their own, and are freed if you die. When you **reincarnate** and are too weak to keep them all, the extra ones wait for your soul and a “Find Lost Beast” quest brings them back ([[reincarnation]]).",
                "see combat reincarnation life-arts");

        HelpContent.add("locations", "Locations, Here and People here", G4, "Known places, the tile you stand on, and the people around you.", "locations places known here people tile cities sects dungeons distance go route find sort",
                "lead Three small tools about **where** things are.",
                "h2 Locations",
                "img win-locations.png|The Locations window.",
                "p ((Locations)) or {L}: every place you have been to or heard of. The **Find** box and the check boxes (cities, sects, dungeons, other) filter; sort by nearest first or by name. Each row shows the place, its coordinates, the distance in tiles, what it is (a city with its population, a sect, a dungeon kind, a spirit vein, or just terrain) and two links: **go** (walk there) and **route** (preview the trip). Click a city or sect name for its full report.",
                "h2 Here",
                "p ((Here)) describes the tile you stand on: level, biome, who is in it, how crowded it is against its capacity, herbs and metal left, beasts, bounties, shops. It costs no time.",
                "h2 People here",
                "p ((People here)) lists the cultivators in your tile, **numbered** (quest targets first). Those numbers are what `talk 3`, `spar 3`, `attack 3` and `invite 3` use. For more tools, use [[browse|Browse]].",
                "see map browse tile-info");

        HelpContent.add("painted-map", "Painted map", G4, "The world as an ink-and-wash painting.", "painted map picture world painting regions seas ranges rivers save png",
                "lead ((Painted map)) paints the whole world as a map in ink and wash: mountains, forests, rivers, the sea, and the **names** of seas, ranges, rivers and plains, which come from the land itself.",
                "img win-painted-map.png|The painted map.",
                "* **Cities and sects appear once you have seen them.** Explore to fill the map in.",
                "* ((Save as PNG)) writes `world_map.png` to the exports folder ([[export]]). The picture repaints when you resize the window.",
                "tip The painted map is for looking; for clicking and walking use the [[map]], or the [[world-overview|World overview]].",
                "see map world-overview export");

        HelpContent.add("biography", "Biography and Journal", G4, "The story of one life in charts and events.", "biography journal charts life events level wealth friends kills history",
                "lead ((Biography)) (also {J}, and the Biography button in any [[character]] window) draws three charts of a life and lists its events.",
                "img win-biography.png|A Biography.",
                "* Charts: **level by year**, **wealth** (log scale) and **friends and kills**. They are recorded for player characters and followed cultivators, and fill in as game years pass.",
                "* The text shows age, level, kills, sect, potential, and every notable event from the [[chronicle]] that involves them.",
                "p ((Journal)) (typed `journal [n]`) prints your own story as text: chronicle entries about you, your latest notices and a yearly sample of your life.",
                "see character chronicle story");

        HelpContent.add("story", "Story and run statistics", G4, "Story objectives, run statistics and the hall of fame.", "story objectives run statistics hall of fame retire export lives peak totals brutal",
                "lead Two windows about the arc of your whole game.",
                "h2 Story",
                "img win-story.png|The Story window.",
                "p ((Story)) shows the chain of **objectives** of a Story start, which are done, which is current, and its reward. A character without a story says so. Typed: `story`.",
                "h2 Run statistics",
                "img win-run.png|The Run statistics window.",
                "p ((Run stats)) summarises the **whole run**: every body you have lived in, how each life ended, peaks, kills, potential, totals (peak wealth, deepest dungeon, companions tamed, sects and cities founded, children, loved ones outlived). Buttons: ((Export CSV)), ((Hall of fame)) (the saved hall), ((Retire run…)) (records the run in the hall of fame, asks first; the game goes on). A Brutal run is recorded automatically when it ends. Typed: `runstats`, `halloffame`, `retire`, `export run`.",
                "see first-steps reincarnation biography");

        HelpContent.add("cheats", "Cheats and Edit Self", G4, "Developer tools: use them to experiment.", "cheats cheat edit self ss level potential kills weapon heal reset track developer",
                "lead These tools change the game for good. They are there for experiments, testing and fun, not as part of the story.",
                "img win-cheats.png|The Cheats window.",
                "p ((Cheats)) opens a small window. **Target** is `self` or the `#id` of anyone. Each button runs the command `cheat <target> <what> <value>`:",
                "table Button|Effect",
                "row ((Add spirit stones))|Adds that many stones (default 10,000).",
                "row ((Set major level (0-10)))|Sets your realm; the level becomes major x 10 + 1.",
                "row ((Set potential (1-100)))|Sets potential.",
                "row ((Set kill count))|Sets your kills.",
                "row ((Give a weapon of level (1-10)))|A new weapon of that level.",
                "row ((Restore cultivation))|`heal`: fills cultivation to its maximum.",
                "row ((Clear quests))|`reset`: empties the quest queues.",
                "row ((Track))|Adds the target to the NPC tracker.",
                "p ((Edit Self)) (typed `e`) opens the **character editor**: first and last name, trait, potential, alignment and gender. It costs no time.",
                "warn Cheats cannot be undone and are visible in the log. Save first (see [[saves]]).",
                "see saves me");
    }

    // ================================================================== game systems
    static void systems() {
        HelpContent.add("combat", "Fighting", G7, "Fighting level, win chances, challenges, fleeing, kill or spare.", "combat fight battle win chance fighting level power flee escape kill spare forbidden technique challenge spar attack preview lethal death duel injured deathmatch loot",
                "lead Every fight is decided by a comparison of **fighting levels** plus a roll. You can see the odds **before** you commit.",
                "h2 Fighting level",
                "p Your fighting level (called *power* in previews) is **(level + weapon + armour + martial technique + movement technique) / 5**, plus bonuses (the Iron Body trait, the Cheater trait, a weapon enchantment, your companions, and for a defender in a place with arrays, the array's bonus). It is on your [[stats]] sheet. Better gear and techniques raise it as surely as levels do.",
                "h2 The odds",
                "p The chance that **you** win is about **50% + 15% per fighting level you are ahead** (minus 15% per level you are behind), clamped to 0-100%; a Lucky trait adds 45. Equal fighters: a coin toss. Two levels ahead: 80%.",
                "p **Preview** it: `preview #<id>` or ((Preview fight)) in [[browse|Browse]]. It shows both fighters' power, your win chance, how likely the fight is **lethal**, your **escape** odds and theirs, the relationship and their caution.",
                "h2 Types of fight",
                "table Fight|What it is",
                "row **Spar** ((Spar))|A friendly fight. Nobody dies. Good for making friends.",
                "row **Attack** ((Attack))|A real fight. If your win chance is under 35% or the death chance is 50% or more, the game asks to confirm first.",
                "row **Challenge**|Someone challenges you: “Fight” or “Slip away” (escape can fail). Strangers and dislikers may challenge only a few times a turn (Settings, *Challenges per turn*), but **rivals, arch-enemies and enemies at war always get through**.",
                "row **Beasts**|Beasts attack by themselves in the wild; crowded tiles (hotspots) are ambushed ([[world-events]]).",
                "h2 When is a fight lethal?",
                "p Between cultivators, by the relationship: **friends 0%**, strangers **1%**, dislike **5%**, rival **25%**, arch-enemy **75%**, a wanted enemy **100%**. A beast is lethal only if it out-levels the fighter by more than 5 or ambushes; at or near your level it will not kill you. A lost fight that is not lethal just leaves you **injured**: cultivation x0.7 until your next level-up.",
                "h2 Fleeing",
                "p When you are outmatched the game asks **Flee** or **Fight**. Escape is not certain: it depends on movement techniques and levels (the Runner trait is nearly always successful). Policies answer for you in AUTO ([[duties]]).",
                "h2 The Forbidden Technique",
                "p In a deadly fight you may be offered it: it adds about the square root of your potential to your fighting level at the cost of years of your lifespan, and it can kill you. A rare chance of +1 potential on surviving. Policy: *use the Forbidden Technique in a deadly fight* (off by default).",
                "h2 After you win",
                "p You choose **Kill** or **Spare** (only cultivators; beasts are always killed). Killing takes their items, and gives you blood for pills, and spirit stones from beasts. The dead person's close friends think much worse of you afterwards and may come for **Revenge**. Sparing changes nothing else. Policy: after winning, always spare / kill evil only / kill if wronged / always kill ([[duties]]).",
                "img win-decision.png|A kill-or-spare decision.",
                "warn In Originis during the first year nobody may start a fight (a one-year truce). After that, even a city is not safe from rivals.",
                "tip The three habits that keep you alive: **preview before attacking**, keep your **policies** set, and let **auto-pause** (Settings) stop fast-forward the moment you are attacked.",
                "see duties browse stats world-events");

        HelpContent.add("sect", "Sects and cities", G7, "Joining and leading sects, founding and ruling cities.", "sect city found lord master member rank disciple elder points mission donate library array war peace alliance tribute territory tax treasury population shops tournament festival originis",
                "lead Cities and sects are the two organisations of the world. NPCs found them yearly in proportion to the number of cultivators; you can join or found them too.",
                "h2 Sects",
                "* **Join** one by standing in its tile and using ((Join sect here)) / `join`. A sect may ask for a **craft** (trait), a **potential** and **level** floor, an **alignment**, a **gender** or a **family name**; the sect info tells you what. A sect also has a member cap.",
                "* **Ranks**: Outer Disciple, Inner Disciple, Elder, Master (and Founder). The master promotes members over time and can ((Promote selected)).",
                "* **Sect points** come from missions (forage, mine or hunt targets that the master posts each year) and donations. Spend them in the sect's shop and library (techniques and items cost points).",
                "* Members get **extra cultivation** every week, bigger when the sect is high-level (its stored materials). Members of a sect at war with another fight when they meet.",
                "* **Found** your own at Major 2 (`found sect`) in any tile with no sect. You become master: you set the **recruitment rules**, promote, recruit, declare ((Declare war here)), make ((Peace)), ((Propose alliance here)). **Resign** loses your rank and points.",
                "* Wars end by themselves in a few years (a truce, or a renewed war); allies hold gatherings; a sect with ambitious members can suffer treachery. Those events appear in the log and the [[chronicle]].",
                "h2 Cities",
                "* A **city** is a tile with a lord, a population, a treasury, shops, a library, an auction and a market. **Found** one (or claim a lordless one) at Major 2 with ((Found / claim city)) / `found city`.",
                "* The lord receives the **tax**: once a year population / 100 (half the lord's, half the treasury). A richer treasury raises the **city level** (up to 10), which raises the number of shop slots (3 per level) and the best goods sold.",
                "* The lord can ((Buy city array)) (protection), ((Hold tournament)), ((Entice merchant)). A **tournament** is open to a range of realms: ((Register for tournament)) or watch it.",
                "* **Arrays** protect a place: attackers must break the array and defeat its defenders to take it, and defenders get a level boost during the fight.",
                "* Cities have festivals each season ([[world-events]]) and grow in population over time.",
                "p The central city **Originis** is special: no overcrowding, protected from destruction, and the heart of the world. Details of any city or sect: ((City / sect details…)) in [[tile-info]]; the lists of all of them in [[rankings]]; your own in [[manage]].",
                "see manage squad economy world-events");

        HelpContent.add("economy", "Money, shops and goods", G7, "Spirit stones, working, selling, shops, the auction and prices.", "economy money spirit stones ss crystals price shop merchant forage mine craft sell buy herbs metal pills arrays prices rates profit trade caravan tax",
                "lead Money is **spirit stones** (ss). Spirit crystals (1 = a million stones) and bigger coins exist but the game shows everything in stones.",
                "h2 Earning",
                "* **Work**: `forage` herbs, `mine` metal, `craft` with your profession (Alchemists make pills from herbs, Blacksmiths weapons from metal, Tailors robes, Scribes arrays). A tile's herbs and metal run out and regrow slowly.",
                "* **Hunt beasts**: a killed beast gives spirit stones (more for higher levels). Cities post **bounties** on beasts.",
                "* **Sell** in a city: `sell`, ((Sell all (city))). **Merchants** buy and sell for profit between cities.",
                "* Tax if you are a city lord ([[sect]]); sell techniques to a library (20% fee); luxuries go to the **auction** ([[market]]). Shops buy anything their owner can pay for. A cultivator who is not an alchemist can take **Blood** (from kills) to an alchemist, who refines 1,000 Blood into a Potential Pill for a fee.",
                "h2 Prices",
                "table Item|Price (level L = 1-10)",
                "row Herb, metal|L^2.5 x 10",
                "row Pills|L^2.5 x 100",
                "row Weapons, clothing|L^2.5 x 1,000",
                "row Arrays|L^2.5 x 500",
                "row Library technique|potential^2 x 1,000",
                "h2 Buying and selling",
                "* `list shop [type=weapon lvl>=30 price<=5k afford=1 sort=price]` shows the shops' stock; `buy 3` buys row 3; the Browse window's ((Buy selected)) does the same.",
                "* A **merchant's shop** pays sellers 55% of the price, charges buyers 150%, and restocks from the city pool at 30% (set by the owner in [[manage]]). The **city pool** pays 50%. Shops only stock items up to a level that depends on the city level and the owner's realm.",
                "* The **goods market** sells food, wine and poison ([[life-arts]]).",
                "tip Compare before you sell: a merchant shop with a good buy rate pays more than the city pool. Gear you do not wear is sold by ((Sell all (city))), so keep a spare you want.",
                "see market manage sect life-arts");

        HelpContent.add("reincarnation", "Reincarnation, rebirth and death", G7, "What happens at the limit of your potential, and when you die.", "reincarnation rebirth rope cap death die take over killer child spectate ghost lives soul lineage true immortal",
                "lead Your potential is a rope: it carries you only so far. At the end of it you can **be reborn**; when you die you may continue as someone else.",
                "h2 The rope",
                "p The highest level your potential reaches is **10 x (gates passed) + 9** (9, 19, 29... up to 99; potential 100 has no limit). Once you are at **Major 3 or more** and have reached that level, the quest **Reincarnate** appears (an alert, priority 95) and ((Lineage)) / `lineage` tells you. Doing it (`reincarnate`, or Do Quest on the alert) keeps **the same character** and gives a second youth: age 18, level 1, cultivation 0, a fresh lifespan, failed breakthroughs forgotten, and **+5 potential**. Name, family, sect, relationships, wealth, items and techniques stay. Brutal starts do not allow it.",
                "p The Stats window's **Rope** line, the Family window's **Past lives** tab and the Run statistics track your lives.",
                "h2 When you die",
                "p A dialog **After death** offers: take over the **killer** (if it was a cultivator), your **best living child**, **any living cultivator by id**, or **spectate**. Your duty switches and policies carry over. On **Brutal**, death is final.",
                "p Special cases: a **Ghost** physique does not die once: it wanders to a city and is reborn as a new character. A **True Immortal** (Major 10) revives. Companions beyond your new limit wait for your soul ([[companions]]).",
                "see cultivation companions family story");

        HelpContent.add("life-arts", "Food, wine, poison and music", G7, "The arts of life: who can do what.", "life arts food wine poison music chef drunken poisoner musician instrument play coat eat drink make goods market conditions",
                "lead Five traits have a **life art**. Anyone can *use* the results, but only the matching trait can *make* them: **Chef** (food), **Drunken** (wine), **Poisoner** (poison), **Musician** (instruments, music). Beast Tamers tame ([[companions]]).",
                "table Art|What it does",
                "row **Make** (`make food¦wine¦poison¦instrument`)|Uses 50 herbs per unit; the number of units grows with your profession level. The level of the product is the herb level.",
                "row **Eat** (`eat`)|+15% cultivation x level ratio for 13 weeks (26 weeks and x1.5 for a Chef); cures poison of equal or lower level.",
                "row **Drink** (`drink`)|Drunk for 4 weeks: +25% cultivation, but -1 fighting level (Drunken: better).",
                "row **Play** (`play`)|Extra cultivation ticks; everyone present is **inspired** (+10% cultivation for 4 weeks) and may like you more; a city pays tips. Needs an instrument.",
                "row **Poison** (`poison <person>`, `coat`)|A poisoned victim cultivates at 60% and fights worse for 13 weeks, and may die if the poison outranks them. `coat` poisons your blade for 3 fights. Only Poisoners can make it; selling it needs a Poisoner buyer.",
                "p Food spoils fastest, then wine, then poison. Your conditions (nourished, drunk, inspired, poisoned) are on the [[stats]] and the [[backpack]] window; portions are sold in the city **goods market** ([[market]]). Seasonal festivals give cooks, brewers and musicians a bonus trade.",
                "see backpack market companions");

        HelpContent.add("world-events", "World events", G7, "Festivals, beast tides, trials, treasures, crowds and hotspots.", "events festival beast tide celestial trial heaven treasure hotspot crowd overcrowded ambush dungeon ruins lair haunted martial spirit vein auction tournament season",
                "lead The world has its own calendar of things happening, whether or not you take part.",
                "h2 Seasonal festivals",
                "p Every season each city of 500 or more has a festival: a **Blossom Festival** in spring, a **Martial Fair** in summer (the lord may hold a tournament), a **Harvest Fair** in autumn (shops restock), a **Lantern Night** in winter. Attendees may get inspired and the city treasury grows.",
                "h2 Dungeons",
                "table Place|What is there",
                "row Lost Ruins|A treasure chest and a random technique.",
                "row Beast Lair|Three forced fights with beasts.",
                "row Martial Trial|A test that can upgrade a technique.",
                "row Haunted Grounds|A small chance of +1 potential and extra cultivation.",
                "row Celestial Trial|A temporary place (it closes after about 10 weeks) with three boss fights, lots of cultivation, a chance of +1 potential and of a technique. One appears each year in the wilds.",
                "p Quests such as **Explore Dungeon** (an alert) point you at one that fits your level.",
                "h2 Beast tides and treasures",
                "* When a Beast Lair has too many beasts, a **Beast Tide** spills them into the four neighbouring tiles each year (and can hurt a neighbouring city).",
                "* Every year a **Heaven-sent treasure** appears in the wilds: a technique, instrument, poison, Potential Pill, regular pill, clothes, weapon or array. Everyone within 20 tiles gets a quest to claim it; the first to arrive wins. A claimed item can be put up at a city auction ([[market]]).",
                "* A **Spirit Vein** tile (✦) is a rich cultivation spot.",
                "h2 Crowds and hotspots",
                "p From year 10, a tile with more people than its capacity (a fixed share of the starting population; cities have four times; Originis is exempt) turns into a **hotspot**: its level surges and beasts **ambush** the excess each week, killing whom they beat. Red outlines on the [[map]] (Crowd layer) show them. A hotspot ends when the tile drops under 80% of capacity. You will receive a **Disperse** quest (an alert) when your tile is one. Move somewhere quieter.",
                "warn At very large populations (200,000 living), a periodic purge removes some cultivators of every realm.",
                "see map sect combat");
    }

    // ================================================================== terminal
    static void terminal() {
        HelpContent.add("terminal", "Terminal commands: how they work", G8, "Typing instead of clicking: the rules and a few examples.", "terminal commands console command box type help examples shortcuts list filter sort person id bang confirm",
                "lead Everything the buttons do can be **typed**, and some things can only be typed. Type commands in the command box of the **Move tab**, or in the terminal window if you play without the map.",
                "h2 Rules",
                "* Commands are case-insensitive, with short forms for the common ones (`w a s d`, `i`, `l`, `r`, `q`, `e`, `z`, `f`, `p`).",
                "* Commands that **only look** cost no time; commands that **act** (move, work, fight) use a turn and let the world move ([[turn]]).",
                "* A **person** is a row number from the last `people` or `list` view, or `#<id>` (the id is in the character window and in tables). Leave the person out of `talk`, `spar`, `attack`, `invite` and `recruit` and one suitable person here is picked at random.",
                "* A leading `!` means “I already confirmed this”: `!resign` skips the question.",
                "* **Coordinates** can be the displayed numbers (`1500 900`) or tile numbers (`15 9`).",
                "h2 A few examples",
                "table I want to...|Type",
                "row look around|`here` then `people`",
                "row find strong evil cultivators in my tile|`list people 50 lvl>=20 aff=evil sort=lvl desc`",
                "row know if a fight is wise|`preview #123`, then `spar #123` to be safe",
                "row walk somewhere safely|`route 1500 900`, then `goto 1500 900`",
                "row gather and sell|`forage` (repeat), travel to a city, `sell`",
                "row shop|`list shop type=weapon afford=1 sort=price`, `buy 3`",
                "row hand over the controls|`auto 50` (50 turns), `watch 200 for breakthrough`, `wait 52`",
                "row do something about a quest|`q`, `qdo 2`, `seek 4821 friend`",
                "row save|`save` or `save before-the-war`",
                "h2 The list language",
                "p `list people¦monsters¦shop¦bag¦places [limit] [filters] [sort=key [desc]]`. Filters are `key=text` (contains), `key!=text`, `key>=n`, `key<=n`, `key>n`, `key<n`; a bare number is the row limit; a bare word is a name filter. Keys for each kind:",
                "listkeys",
                "p `5k` stands for 5,000 (and `m` for millions) in price filters. `limit <n>` sets the default number of rows (1-500). The Browse window ([[browse]]) is the same thing with boxes.",
                "see terminal-ref terminal-more terminal-topics keys");

        HelpContent.add("terminal-ref", "Command reference (generated)", G8, "Every line of the game's own command list.", "commands reference list help syntax move modes duties policy quests info lists pick seek shops work roles shop do script look gear market life run wait system",
                (java.util.function.Supplier<String[]>) HelpContent::terminalReference);

        HelpContent.add("terminal-more", "Other terminal commands", G8, "Commands that are not in the main list.", "commands save load control follow find preview export story tutorial settings notices recap family relations music cheat guide chase goquest quit diagonal",
                (java.util.function.Supplier<String[]>) HelpContent::terminalMore);

        HelpContent.add("terminal-topics", "Command manual pages (generated)", G8, "`help <topic>` pages exactly as the game prints them.", "manual topics help map route time watch journal history equip compare techniques notes city rules sect runstats digest market dash",
                (java.util.function.Supplier<String[]>) HelpContent::terminalTopics);
    }

    // ================================================================== reference
    static void reference() {
        HelpContent.add("keys", "Keyboard shortcuts", G9, "Every key, generated from the game's key table.", "keys keyboard shortcuts f1 wasd arrows space hotkeys control save pause",
                (java.util.function.Supplier<String[]>) HelpContent::keyTable);

        HelpContent.add("glossary", "Glossary", G9, "Words used in the game and this Help.", "glossary terms definitions alert array bounty duty hotspot inhibitor major minor potential rope spirit stone squad technique trait",
                "table Word|Meaning",
                "row **Alert**|A quest you must do yourself. See [[quests]].",
                "row **Array**|A magical item installed in a place to protect its features. See [[sect]].",
                "row **Bounty**|A reward posted in a city for hunting beasts or a wanted cultivator.",
                "row **Breakthrough**|Passing from one major realm to the next. See [[cultivation]].",
                "row **Companion**|A tamed beast that follows you. See [[companions]].",
                "row **Duty**|A chore your character does by itself while its switch is on. See [[duties]].",
                "row **Fighting level**|The number that decides fights (also “power”). See [[combat]].",
                "row **Hotspot**|An overcrowded tile where beasts ambush. See [[world-events]].",
                "row **Inhibitor**|Grows by one with every failed breakthrough; each halves your cultivation speed.",
                "row **Level**|1 to 100; every ten levels is a major realm. See [[cultivation]].",
                "row **Major / minor**|The realm (0-10) and the step inside it (1-10).",
                "row **Originis**|The central city of the world, at [1500, 1500].",
                "row **Potential**|1-100, the ceiling of your talent.",
                "row **Rope**|The level your potential can carry you to before you must reincarnate. See [[reincarnation]].",
                "row **ss, sc, dc**|Spirit stones, spirit crystals (1,000,000 ss), and the next coin up (1,000,000 sc).",
                "row **Squad**|A party of travelling cultivators.",
                "row **Technique**|A learned martial or movement art. See [[techniques]].",
                "row **Tick / turn**|One week of game time. See [[turn]].",
                "row **Trait**|What a character is gifted at (see below).",
                "h2 Traits",
                "table Trait|Gift",
                "row Alchemist, Blacksmith, Tailor, Scribe|Craft pills, weapons, clothing, arrays.",
                "row Gatherer, Miner|Better at gathering herbs and metal.",
                "row Merchant|Runs shops and trades between cities.",
                "row Friendly|Makes friends easily.",
                "row Leader|Founds cities and sects; leads larger squads.",
                "row Innovative|Creates techniques and enchants weapons.",
                "row Runner|Escapes fights.",
                "row Lucky|Fortune: +45 to win chance, extra cultivation, more loot.",
                "row Iron Body|Natural armour in fights.",
                "row Spirit Vein|Cultivates 1.5 times faster.",
                "row Heavenly Root|Techniques level up faster.",
                "row Ghost|Does not die once: reborn in a city.",
                "row Cheater|A rare bonus to fighting level.",
                "row Beast Tamer, Chef, Drunken, Poisoner, Musician|The arts of [[life-arts]] and [[companions]].",
                "row Monster, Beast|Not playable: beasts, and the legendary monsters that awaken from them.",
                "see cultivation combat");

        HelpContent.add("faq", "Questions and troubleshooting", G9, "Quick answers to common problems.", "faq troubleshooting problem stuck nothing happens button does nothing cannot sell do quest too slow text size lost save crash hints music sound died",
                "h3 Nothing happens when I press a button",
                "p Check the status text at the top right. **▶ Simulation running** means the game is playing itself (AUTO, a script, Watch or a long walk): press ((Stop)) or ((⏸ Pause)). **⏸ PAUSED**: press Pause again. **◆ Waiting for input** means it is your move.",
                "h3 The game is slow",
                "p Pick a faster speed (0ms) in the speed bar; close windows you do not need (open windows refresh every second or so); lower the text size or switch off place pictures in [[settings]].",
                "h3 Do Quest says I am not there",
                "p You must stand on the quest's target tile. Use ((▶ Go)) in the status bar or ((Go there)) in the quest panel, then Do Quest. See [[quests]].",
                "h3 I cannot sell / buy",
                "p Selling and buying need a **city** (gold tile). `sell` also needs something sellable: gear you wear and your best spare are kept. See [[economy]].",
                "h3 A button I read about is missing",
                "p Windows and tabs were rearranged over time; use the search box of this Help or the [[world|World tab]] page. Everything has a typed command ([[terminal-ref]]).",
                "h3 I lost my progress",
                "p Look at the **Saves** window: there are rotating autosaves, a quick save, and after a crash a `crash-<time>` slot. Each save has a backup. See [[saves]].",
                "h3 The text is too small or too big",
                "p [[settings|Settings]], Text size (70-250%). The Help follows it too.",
                "h3 I want the hints again, or never",
                "p Settings: **First-time hints** on or off, and ((Reset hints)) shows them again.",
                "h3 No sound",
                "p Music needs an audio device; the status button says “♪ no sound” without one. See [[music]].",
                "h3 I died",
                "p Look at the **After death** choices: the killer, a child, any living cultivator by id, or spectating. On Brutal there is no way back. See [[reincarnation]].",
                "see start settings saves terminal");

        HelpContent.add("lore", "The Oldest Order and the world's secrets", G9, "The story that runs through every life, how to follow it, and its commands (no spoilers).", "lore story history world legends secrets myths palace oldest order originis convocation first gate ??? journal clues places lamps seam cross transcend ending",
                "lead The world has a past, and it holds secrets. Nobody tells them all at once. Every human character, whatever the start, can follow the same story if they want it: it begins in the capital.",
                "h2 Where it starts",
                "p At **Originis** stands the **Palace of the Oldest Order**, a sect whose master is only ever called **???**. Nobody knows who he is; the sect needs no player and no NPC to lead it. Walk into Originis and listen: a bell rings, and a voice answers.",
                "p Each **New Year** the Palace opens the **Convocation of the First Gate**, an entrance tournament for cultivators below Major Lvl 5 (eight weeks; register with ((Do top quest)) or `do Register Tournament` at Originis, or take the pinned Palace quest). The best of the field are let in as **Wicks of the Outer Court**. If you lose, the Palace notices anyone who later crosses Major Lvl 2 and sends for them.",
                "h2 Following it",
                "img win-oldest-order.png|The Journal of the Oldest Order (Me tab, Oldest Order).",
                "* The pinned quest **Palace: ...** in your [[quests|Quest Log]] always names what the Order asks next: register, find a place, earn merit, reach a realm.",
                "* ((Oldest Order)) on the Me tab (or `lore`) opens the **Journal**: the road so far, the places you know, everything you have learned, and the scenes you can read again (`lore replay <id>`).",
                "* **???** speaks now and then in a pop-up window; the game waits until you press ((Continue)) (turn that off with Settings or `settings lorepause off`). Rarely he leaves a one-line whisper in your notices.",
                "* Places that belong on no map are scattered over the world. They appear in your known places when the Order points at them; stand there with the right realm and you may learn something, and get a reward.",
                "* Ranks follow your deeds: Outer Court, Inner Court (Major Lvl 2), and one of the Nine Lamps (Elder). There is a last quest. It is long.",
                "* **Giant Footprints**: six optional places near the Thin Sky and the Garrison. Stand on one at Major Lvl 3 or more for a short clue and a rare relic (once each). The Wandering Immortals sometimes tell you where one lies.",
                "h2 How it ends",
                "p At the end of the road the Seam opens, and you meet **the Gardener** in the Outside: the old cultivator whose mind holds the Garden (??? is only his image and cannot leave). He fights the Hollow Court with an array of nine great lamps, and each lamp needs a strong carrier. Then you choose. **Stay** and grow his soldiers: as the Steward (Good: you master the Palace, cull the cruel, give gifts), taking what the world has (Evil: take or raze the Palace) or living as you please (Neutral). A Stay can be undone at any time with `lore leave`. **Leave** (final): become a **lamp-bearer** (Good: the true ending; your descendants get +5 strength and +5 potential for every soldier in their line, and you come back as a Wandering Immortal who cannot die and leaves hints and gifts), **strike at the Gardener** (Evil: 50/50 the array kills you, and your blood gives everyone in the Garden +5 potential for ever; if you are spared you walk the Outside), or **walk out alone** (Neutral: one of many lives on the Outside). Only nine lamps exist: once all nine are carried, the lamp-bearer ending is closed, an attack always ends in death and the hidden ending is locked. When the Gardener dies in the last week of the world, the Garden goes with him: those who could cross choose the Outside or the dark. Your choice changes your alignment. NPC seekers make the same choices. Every ending has a story, funny credits, a line in the Hall of Fame with a score and a line in the Roll of the Crossed (`lore roll`, `lore hall`).",
                "p NPCs the Convocation lets in become **seekers**: they read the places in order in the background and some of them open the Door too, with the same endings.",
                "table Command|What it does",
                "row `lore`|The Journal (a window in the GUI, text in the terminal).",
                "row `lore clues` `lore where` `lore palace`|What you have learned, the places, the Order and its Nine Lamps.",
                "row `lore scenes` `lore replay <id>`|The scenes you have seen / read one again.",
                "row `lore register` `lore join` `lore cross` `lore leave`|Register for the Convocation, join after a pass, and (much later) cross. After a Stay, `lore leave` goes back through the Seam.",
                "row `settings lore on¦off` `lore enable`|Switch the whole story off (nothing of it runs or shows); `lore enable` founds the Palace in a world that began without it.",
                "img win-lore-scene.png|A scene: ??? speaks.",
                "tip You can ignore all of this and play your own game: the story never forces anything, and with `settings lore off` it is gone.",
                "note Everything else the world remembers is in the [[chronicle|Chronicle]] and its hall of legends, in a Story start's objectives ([[story]]) and in the names of places on the [[painted-map|painted map]].",
                "see chronicle story quests painted-map");
    }
}
